window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-3a57a214e212d2cd"]={"versions": [{"id": "FIG-3a57a214e212d2cd", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) innerhalb der AUTOSAR Classic Platform. Das Diagramm visualisiert die Integration des Moduls Diagnostic Log and Trace (DLT) mit dem Diagnostic Communication Manager (DCM), der Runtime Environment (RTE), einer Software-Komponente (SWC) sowie einem externen Diagnosetester zur Übertragung von Log-Daten über UDS (Unified Diagnostic Services) mittels Response On Event (ROE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Client / Diagnosetester</strong>: Externe Entität (dargestellt als Person mit Tester-Laptop), initiiert ROE-Dienste und empfängt UDS-Diagnoseantworten.</li>\n<li><strong>SWC (Software Component)</strong>: Anwendungskomponente oberhalb der RTE, Erzeuger von Log-Nachrichten.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Middleware-Schicht zur Vermittlung von Funktionsaufrufen zwischen SWC und Basissoftware.</li>\n<li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Kernmodul inklusive Subkomponente <em>DLT comunication module</em>, zuständig für Log-Aggregation, Pufferung und Traffic Shaping.</li>\n<li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Verarbeitung von UDS-Diagnoseanfragen und Verwaltung von ROE-Ereignissen.</li>\n<li><strong>Schnittstellen & Interaktionen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Funktionsaufruf von SWC an DLT.</li>\n<li><code>Dlt_ReadData()</code>: Aufruf vom DCM an DLT zur Datenabholung.</li>\n<li><em>ROE event for Dlt_ReadData</em>: Ereignissignalisierung von DLT an DCM.</li>\n<li><em>Response to Dlt_ReadData</em>: Datenübermittlung vom DLT an DCM.</li>\n<li>UDS-Kommunikation: ROE-Aktivierung und Datenempfang zwischen externem Client und DCM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei nummerierte Sequenzpfade (violette Kreise für Konfiguration/Trigger, cyanfarbene Kreise für Datenfluss):</p>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 1 (Violett – ROE-Aktivierung und Triggerung)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Der externe Client aktiviert ROE über UDS innerhalb seines Berechtigungskontexts (<em>within own security level</em>) am DCM.</li>\n<li>Schritt 2: DLT meldet ein ROE-Ereignis für <code>Dlt_ReadData</code> an das DCM (<em>ROE event for Dlt_ReadData</em>).</li>\n<li>Schritt 3: DCM führt den Aufruf <code>Dlt_ReadData()</code> in Richtung DLT aus, um die bereitgestellten Daten abzurufen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 2 (Cyan – Logging und Datentransport)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Die SWC sendet eine Log-Nachricht via <code>Dlt_SendLogMessage()</code> durch die RTE an das DLT-Modul (grünes Datenpaket symbolisiert den Fluss).</li>\n<li>Schritt 2: DLT sammelt die eingehenden Nachrichten und wendet Traffic Shaping an (<em>DLT collects messages +Trafic shaping</em>).</li>\n<li>Schritt 3: DLT übergibt die aggregierten Log-Daten als Antwort an das DCM (<em>Response to Dlt_ReadData</em>).</li>\n<li>Schritt 4: DCM sendet die Log-Daten über das UDS-Protokoll an den externen Client (<em>Receive log data over UDS</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den Use Case des Loggings über UDS-Diagnosedienste (Service 0x86 ResponseOnEvent in Kombination mit ReadDataByIdentifier 0x22). Für Entwickler und Integratoren verdeutlicht es:</p>\n<ul class=\"fig-list\">\n<li>DLT agiert bei UDS-Logging nicht als aktiver Protokollsender auf dem Bus, sondern dient als Datenquelle für das DCM.</li>\n<li>Das DCM steuert die diagnostische Außenkommunikation gemäß aktuellem Security-Level.</li>\n<li>Vor der Bereitstellung an DCM puffert das DLT-Modul Nachrichten und führt Traffic Shaping durch, um Diagnosebusse nicht zu überlasten.</li>\n<li>Die API <code>Dlt_SendLogMessage()</code> sowie die interne Übergabeschnittstelle <code>Dlt_ReadData()</code> müssen entsprechend den DLT- und DCM-SWS-Anforderungen konfiguriert und angebunden sein.</li>\n</ul>"}, {"id": "FIG-ae090c4a2df915e5", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) innerhalb der AUTOSAR Classic Platform. Das Diagramm visualisiert die Integration des Moduls Diagnostic Log and Trace (DLT) mit dem Diagnostic Communication Manager (DCM), der Runtime Environment (RTE), einer Software-Komponente (SWC) sowie einem externen Diagnosetester zur Übertragung von Log-Daten über UDS (Unified Diagnostic Services) mittels Response On Event (ROE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Client / Diagnosetester</strong>: Externe Entität (dargestellt als Person mit Tester-Laptop), initiiert ROE-Dienste und empfängt UDS-Diagnoseantworten.</li>\n<li><strong>SWC (Software Component)</strong>: Anwendungskomponente oberhalb der RTE, Erzeuger von Log-Nachrichten.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Middleware-Schicht zur Vermittlung von Funktionsaufrufen zwischen SWC und Basissoftware.</li>\n<li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Kernmodul inklusive Subkomponente <em>DLT comunication module</em>, zuständig für Log-Aggregation, Pufferung und Traffic Shaping.</li>\n<li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Verarbeitung von UDS-Diagnoseanfragen und Verwaltung von ROE-Ereignissen.</li>\n<li><strong>Schnittstellen & Interaktionen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Funktionsaufruf von SWC an DLT.</li>\n<li><code>Dlt_ReadData()</code>: Aufruf vom DCM an DLT zur Datenabholung.</li>\n<li><em>ROE event for Dlt_ReadData</em>: Ereignissignalisierung von DLT an DCM.</li>\n<li><em>Response to Dlt_ReadData</em>: Datenübermittlung vom DLT an DCM.</li>\n<li>UDS-Kommunikation: ROE-Aktivierung und Datenempfang zwischen externem Client und DCM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei nummerierte Sequenzpfade (violette Kreise für Konfiguration/Trigger, cyanfarbene Kreise für Datenfluss):</p>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 1 (Violett – ROE-Aktivierung und Triggerung)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Der externe Client aktiviert ROE über UDS innerhalb seines Berechtigungskontexts (<em>within own security level</em>) am DCM.</li>\n<li>Schritt 2: DLT meldet ein ROE-Ereignis für <code>Dlt_ReadData</code> an das DCM (<em>ROE event for Dlt_ReadData</em>).</li>\n<li>Schritt 3: DCM führt den Aufruf <code>Dlt_ReadData()</code> in Richtung DLT aus, um die bereitgestellten Daten abzurufen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 2 (Cyan – Logging und Datentransport)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Die SWC sendet eine Log-Nachricht via <code>Dlt_SendLogMessage()</code> durch die RTE an das DLT-Modul (grünes Datenpaket symbolisiert den Fluss).</li>\n<li>Schritt 2: DLT sammelt die eingehenden Nachrichten und wendet Traffic Shaping an (<em>DLT collects messages +Trafic shaping</em>).</li>\n<li>Schritt 3: DLT übergibt die aggregierten Log-Daten als Antwort an das DCM (<em>Response to Dlt_ReadData</em>).</li>\n<li>Schritt 4: DCM sendet die Log-Daten über das UDS-Protokoll an den externen Client (<em>Receive log data over UDS</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den Use Case des Loggings über UDS-Diagnosedienste (Service 0x86 ResponseOnEvent in Kombination mit ReadDataByIdentifier 0x22). Für Entwickler und Integratoren verdeutlicht es:</p>\n<ul class=\"fig-list\">\n<li>DLT agiert bei UDS-Logging nicht als aktiver Protokollsender auf dem Bus, sondern dient als Datenquelle für das DCM.</li>\n<li>Das DCM steuert die diagnostische Außenkommunikation gemäß aktuellem Security-Level.</li>\n<li>Vor der Bereitstellung an DCM puffert das DLT-Modul Nachrichten und führt Traffic Shaping durch, um Diagnosebusse nicht zu überlasten.</li>\n<li>Die API <code>Dlt_SendLogMessage()</code> sowie die interne Übergabeschnittstelle <code>Dlt_ReadData()</code> müssen entsprechend den DLT- und DCM-SWS-Anforderungen konfiguriert und angebunden sein.</li>\n</ul>"}, {"id": "FIG-d0ac12e2f5605829", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Informelles Architektur- und Interaktionsdiagramm (Use-Case-Ablauf) innerhalb der AUTOSAR Classic Platform. Das Diagramm visualisiert die Integration des Moduls Diagnostic Log and Trace (DLT) mit dem Diagnostic Communication Manager (DCM), der Runtime Environment (RTE), einer Software-Komponente (SWC) sowie einem externen Diagnosetester zur Übertragung von Log-Daten über UDS (Unified Diagnostic Services) mittels Response On Event (ROE).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>External Client / Diagnosetester</strong>: Externe Entität (dargestellt als Person mit Tester-Laptop), initiiert ROE-Dienste und empfängt UDS-Diagnoseantworten.</li>\n<li><strong>SWC (Software Component)</strong>: Anwendungskomponente oberhalb der RTE, Erzeuger von Log-Nachrichten.</li>\n<li><strong>RTE (Runtime Environment)</strong>: Middleware-Schicht zur Vermittlung von Funktionsaufrufen zwischen SWC und Basissoftware.</li>\n<li><strong>DLT (Diagnostic Log and Trace)</strong>: BSW-Kernmodul inklusive Subkomponente <em>DLT comunication module</em>, zuständig für Log-Aggregation, Pufferung und Traffic Shaping.</li>\n<li><strong>DCM (Diagnostic Communication Manager)</strong>: BSW-Modul zur Verarbeitung von UDS-Diagnoseanfragen und Verwaltung von ROE-Ereignissen.</li>\n<li><strong>Schnittstellen & Interaktionen</strong>:</li>\n<li><code>Dlt_SendLogMessage()</code>: Funktionsaufruf von SWC an DLT.</li>\n<li><code>Dlt_ReadData()</code>: Aufruf vom DCM an DLT zur Datenabholung.</li>\n<li><em>ROE event for Dlt_ReadData</em>: Ereignissignalisierung von DLT an DCM.</li>\n<li><em>Response to Dlt_ReadData</em>: Datenübermittlung vom DLT an DCM.</li>\n<li>UDS-Kommunikation: ROE-Aktivierung und Datenempfang zwischen externem Client und DCM.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm unterscheidet zwei nummerierte Sequenzpfade (violette Kreise für Konfiguration/Trigger, cyanfarbene Kreise für Datenfluss):</p>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 1 (Violett – ROE-Aktivierung und Triggerung)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Der externe Client aktiviert ROE über UDS innerhalb seines Berechtigungskontexts (<em>within own security level</em>) am DCM.</li>\n<li>Schritt 2: DLT meldet ein ROE-Ereignis für <code>Dlt_ReadData</code> an das DCM (<em>ROE event for Dlt_ReadData</em>).</li>\n<li>Schritt 3: DCM führt den Aufruf <code>Dlt_ReadData()</code> in Richtung DLT aus, um die bereitgestellten Daten abzurufen.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ablaufpfad 2 (Cyan – Logging und Datentransport)</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Schritt 1: Die SWC sendet eine Log-Nachricht via <code>Dlt_SendLogMessage()</code> durch die RTE an das DLT-Modul (grünes Datenpaket symbolisiert den Fluss).</li>\n<li>Schritt 2: DLT sammelt die eingehenden Nachrichten und wendet Traffic Shaping an (<em>DLT collects messages +Trafic shaping</em>).</li>\n<li>Schritt 3: DLT übergibt die aggregierten Log-Daten als Antwort an das DCM (<em>Response to Dlt_ReadData</em>).</li>\n<li>Schritt 4: DCM sendet die Log-Daten über das UDS-Protokoll an den externen Client (<em>Receive log data over UDS</em>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Schaubild illustriert den Use Case des Loggings über UDS-Diagnosedienste (Service 0x86 ResponseOnEvent in Kombination mit ReadDataByIdentifier 0x22). Für Entwickler und Integratoren verdeutlicht es:</p>\n<ul class=\"fig-list\">\n<li>DLT agiert bei UDS-Logging nicht als aktiver Protokollsender auf dem Bus, sondern dient als Datenquelle für das DCM.</li>\n<li>Das DCM steuert die diagnostische Außenkommunikation gemäß aktuellem Security-Level.</li>\n<li>Vor der Bereitstellung an DCM puffert das DLT-Modul Nachrichten und führt Traffic Shaping durch, um Diagnosebusse nicht zu überlasten.</li>\n<li>Die API <code>Dlt_SendLogMessage()</code> sowie die interne Übergabeschnittstelle <code>Dlt_ReadData()</code> müssen entsprechend den DLT- und DCM-SWS-Anforderungen konfiguriert und angebunden sein.</li>\n</ul>"}], "trans": [{"from": "FIG-3a57a214e212d2cd", "to": "FIG-ae090c4a2df915e5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Bildabmessungen und Rahmensetzung minimal angepasst (927x593 px auf 926x605 px mit veränderten Rändern/Schärfung).</li>\n<li>Keine inhaltlichen Änderungen an Komponenten, Interaktionsschritten, Nummerierungen oder Beschriftungen erkennbar.</li>\n</ul>"}, {"from": "FIG-ae090c4a2df915e5", "to": "FIG-d0ac12e2f5605829", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
